     2→# ABOUTME: Test parsing of $#array syntax (array length)
     3→# ABOUTME: Verify $#array and $#$ref forms are supported
     4→use 5.42.0;
     5→use utf8;
     6→use lib 'lib';
     7→use Test::More tests => 7;
     8→use Chalk::Grammar::BNF;
     9→use FindBin qw($RealBin);
    10→use Chalk::Parser;
    11→use File::Spec;
    12→
    13→# Load grammar from BNF file
    14→my $bnf_file = File::Spec->catfile($RealBin, '..', 'grammar', 'perl.bnf');
    15→open my $grammar_fh, '<:utf8', $bnf_file or die "Cannot open $bnf_file: $!";
    16→my $bnf_content = do { local $/; <$grammar_fh> };
    17→close $grammar_fh;
    18→my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program');
    19→
    20→my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    21→
    22→# Suppress warnings during parsing
    23→local $SIG{__WARN__} = sub {};
    24→
    25→# Basic array length
    26→ok($parser->parse_string('$#array'), 'array length variable');
    27→ok($parser->parse_string('$#output_lines'), 'array length with underscores');
    28→
